from ute_common_config.config import Config
from ute_common_validator.validator import IsOneOf, IsInstance, Assert, ValidLength, Or, And, IsIpAddress, IsFqdn

from .base import PduMixin
from .exception import WrongSchemaIndex
from .schemas.transport import TrsSchema1


class UTE_WMP(PduMixin):
    """This class describes the configuration parameters for the UTE WMP testline variant."""

    def __init__(self, enb_hw_type, pdu_ip, pdu_type, enb_pdu_outlet, iphy_pdu_outlet, iphy_pdu_ip=None,
                 iphy_pdu_type=None, bbmod1_pdu_outlet=None, bbmod2_pdu_outlet=None, host_ip='127.0.0.1',
                 trs_ips=TrsSchema1(), top_ip='10.44.136.254', vlan_ids=None):
        """
        :param string      enb_hw_type:          eNB hardware version. Supported values: FSME, FSMF, FSIH, FSIP, ASIA,
                                                 ASIB, ASIL, ASOD, ASOE, ASOF, ASIM
        :param string      pdu_ip:               PDU IP address.
        :param string      pdu_type:             PDU type. Supported values: APC, SWH, ATEN, ATEN24, DCS, BBOX, MOXA,
                                                 FACOM, S7, EPC, EPCNC, HBTE.
        :param integer     enb_pdu_outlet:       PDU outlet number eNB is connected to.
        :param integer     iphy_pdu_outlet:      PDU outlet number I-PHY is connected to.
        :param string      iphy_pdu_type:        IPHY PDU type. Supported values: APC, SWH, ATEN, ATEN24, DCS, BBOX,
                                                 MOXA, FACOM, S7, EPC, EPCNC, HBTE.
        :param string      iphy_pdu_ip:          IPHY PDU IP address.
        :param integer     bbmod1_pdu_outlet:    PDU outlet number bbmod1 is connected to.
        :param integer     bbmod2_pdu_outlet:    PDU outlet number bbmod2 is connected to.
        :param string      host_ip:              IP address of test line control PC. Supports FQDN format.
        :param TrsSchemas  trs_ips:              Provides transport ip addresses of eNB and Iphy. Ips can be set via
                                                 TrsSchemas available in schemas.
        :param string      top_ip:               IP address of ToP server.
        :param integer list vlan_ids:            Allowed vlan_ids for the testline

        """
        super(UTE_WMP, self).__init__()
        pdu_type_validator = IsOneOf(*self.PDU_TYPES_ALLOWED)
        outlet_validator = IsOneOf(*self.get_allowed_pdu_outlets(pdu_type))
        device_types_allowed = ["FSME", "FSMF", "FSIP", "FSIH", "ASIA", "ASIB", "ASIL", "ASOD", "ASOE", "ASOF", "ASIM"]
        device_validator = IsOneOf(*device_types_allowed)
        trs_ip_validator = IsInstance(Config)
        ip_validator = IsIpAddress()
        host_validator = Or(ip_validator, IsFqdn())
        iphy_outlet_validator = IsOneOf(None, *self.get_allowed_pdu_outlets(iphy_pdu_type))
        bbmod_outlet_validator = IsOneOf(None, *self.get_allowed_pdu_outlets(pdu_type))
        vlan_ids_range_validator = Assert(lambda vlanids: all((vlan_id in range(1, 5000) for vlan_id in vlan_ids)),
                                          'vlan_id not in range 1 to 5000')
        vlan_ids_validators = And(IsInstance(list), ValidLength(4, 6), vlan_ids_range_validator, chain=True)
        vlan_id_isnone_validator = Assert(lambda vlanid: vlanid is None, 'vlan_id should be none')
        vlan_ids_validators = Or(vlan_id_isnone_validator, vlan_ids_validators)
        self._set_attr("enb_hw_type", enb_hw_type, device_validator)
        self._set_attr("pdu_ip", pdu_ip, ip_validator)
        self._set_attr("pdu_type", pdu_type, pdu_type_validator)
        self._set_attr("enb_pdu_outlet", enb_pdu_outlet, outlet_validator)
        self._set_attr("iphy_pdu_outlet", iphy_pdu_outlet, iphy_outlet_validator)
        self._set_attr("bbmod1_pdu_outlet", bbmod1_pdu_outlet, bbmod_outlet_validator)
        self._set_attr("bbmod2_pdu_outlet", bbmod2_pdu_outlet, bbmod_outlet_validator)
        self._set_attr("host_ip", host_ip, host_validator)
        self._set_attr("trs_ips", trs_ips, trs_ip_validator)
        self._set_attr("top_ip", top_ip, ip_validator)
        self._set_attr("vlan_ids", vlan_ids, vlan_ids_validators)

        self._set_attr('host', Host(host_ip))
        self._set_attr('fsm', FSMr3(pdu=Pdu(pdu_ip, enb_pdu_outlet, pdu_type),
                                    bbmod1_pdu=Pdu(pdu_ip, bbmod1_pdu_outlet, pdu_type),
                                    bbmod2_pdu=Pdu(pdu_ip, bbmod2_pdu_outlet, pdu_type),
                                    trs_ip=trs_ips,
                                    top_ip=top_ip,
                                    vlan_ids=vlan_ids))
        self._set_attr('iphy', IPHY(pdu=Pdu(iphy_pdu_ip, iphy_pdu_outlet, iphy_pdu_type)))


class ConfigComposer(Config):
    """Class creates new configuration composed from two or more schemas.
    ::

        # Create new configuration with Link
        tl1 = UTE_WMP(...)
        tl2 = UTE_WMP(...)
        tl = ConfigComposer(tl1, tl2)

        # Access to configurations from the python
        tl.pdu_type == tl[1].pdu_type
        tl[2].pdu_type

        # Access to configurations from Robot Framework test
        ${tl.pdu_type}
        ${tl[1].pdu_type}
        ${tl[2].pdu_type}
    """

    def __init__(self, *schemas):
        """
        :param schemas: One or more schemas to link.
        """
        super(ConfigComposer, self).__init__()

        for index, each in enumerate(schemas, start=1):
            self._set_attr(index, each, IsInstance(Config))

    def __iter__(self):
        for index in sorted(self._attributes.keys()):
            yield self._attributes[index]

    def __reversed__(self):
        for index in sorted(self._attributes.keys(), reverse=True):
            yield self._attributes[index]

    def __getattr__(self, item):
        return getattr(self._attributes[1], item)

    def __getitem__(self, item):
        if isinstance(item, int):
            self._is_index_correct(item)
            return self._attributes[item]
        return self._attributes[1][item]

    def _is_index_correct(self, index):
        if index <= 0 or index > len(self._attributes):
            raise WrongSchemaIndex("Schemas are indexed from 1 to number of provided schemas. "
                                   "Linker contains schemas in range {}-{}, requested index is {}."
                                   .format(1, len(self._attributes), index))


class Host(Config):
    def __init__(self, addr='127.0.0.1', username='ute', password='ute'):
        super(Host, self).__init__()

        self._set_attr('addr', addr)
        self._set_attr('username', username)
        self._set_attr('password', password)


class Pdu(Config):
    def __init__(self, addr, port, device):
        super(Pdu, self).__init__()

        self._set_attr('addr', addr)
        self._set_attr('port', port)
        self._set_attr('device', device)


class FSMr3(Config):
    def __init__(self, pdu, bbmod1_pdu=None, bbmod2_pdu=None, trs_ip='10.0.1.2', top_ip='10.44.136.254', vlan_ids=None):
        super(FSMr3, self).__init__()

        self._set_attr('hw_type', 'FSMF')
        self._set_attr('pdu', pdu)
        self._set_attr('bbmod1_pdu', bbmod1_pdu)
        self._set_attr('bbmod2_pdu', bbmod2_pdu)
        self._set_attr('trs_ip', trs_ip)
        self._set_attr('top_ip', top_ip)
        self._set_attr('vlan_ids', vlan_ids)


class IPHY(Config):
    def __init__(self, pdu, trs_ip='10.0.2.2'):
        super(IPHY, self).__init__()
        self._set_attr('pdu', pdu)
        self._set_attr('trs_ip', trs_ip)
